// Bench rack for 40 x 2.0 mL microcentrifuge tubes
// Print orientation: base on XY plane, holes open upward (+Z)

// ---------------- Parameters ----------------
block_x      = 144;   // block length (X), mm
block_y      = 94;    // block width (Y), mm
block_z      = 30;    // block height (Z), mm

cols         = 8;     // holes along X
rows         = 5;     // holes along Y
pitch        = 17;    // centre-to-centre spacing (X and Y), mm

hole_d       = 11.0;  // hole diameter, mm
hole_depth   = 26;    // hole depth from top surface, mm
floor_t      = block_z - hole_depth; // solid floor thickness (4 mm)

overcut      = 0.5;   // extension of cutters past the top face, mm
$fn          = 96;    // curve resolution

// Grid origin so the hole pattern is centred on the block
grid_x0 = -(cols - 1) * pitch / 2;
grid_y0 = -(rows - 1) * pitch / 2;

// ---------------- Model ----------------
difference() {
    // Solid block, centred in X/Y, resting on z = 0
    translate([-block_x / 2, -block_y / 2, 0])
        cube([block_x, block_y, block_z]);

    // 40 tube holes, closed at the bottom (floor_t solid floor)
    for (i = [0 : cols - 1])
        for (j = [0 : rows - 1])
            translate([grid_x0 + i * pitch, grid_y0 + j * pitch, floor_t])
                cylinder(d = hole_d, h = hole_depth + overcut);
}
