// 6-place holder for 20 mL scintillation vials
// Print orientation: upright, block base on XY plane at z = 0

// ---------------- Parameters ----------------
block_len    = 220;   // block length along X (mm)
block_wid    = 40;    // block width along Y (mm)
block_ht     = 30;    // block height along Z (mm)

n_holes      = 6;     // number of vial holes
hole_pitch   = 36;    // centre-to-centre spacing along X (mm)
hole_dia     = 28.0;  // vial hole diameter (mm)
hole_depth   = 26;    // blind hole depth from top face (mm)
floor_thk    = block_ht - hole_depth; // remaining floor thickness = 4 mm

overcut      = 0.5;   // extension of cutters past top face (mm)
$fn          = 128;   // facet count for round holes

// ---------------- Derived ----------------
row_span     = (n_holes - 1) * hole_pitch; // distance first-to-last hole centre

// ---------------- Model ----------------
difference() {
    // Solid block, centred in X and Y, resting on z = 0
    translate([-block_len / 2, -block_wid / 2, 0])
        cube([block_len, block_wid, block_ht]);

    // Row of blind vial holes, open at the top
    for (i = [0 : n_holes - 1]) {
        translate([-row_span / 2 + i * hole_pitch, 0, floor_thk])
            cylinder(d = hole_dia, h = hole_depth + overcut);
    }
}
