$fn = 96;

difference() {
    union() {
        // Collar on the bed
        cylinder(h = collar_h, d = collar_d);
        // Sleeve body rising from collar (slight overlap for clean union)
        translate([0, 0, collar_h - 0.01])
            cylinder(h = total_h - collar_h + 0.01, d = body_d);
    }
    // Straight through-bore, open at both ends
    translate([0, 0, -eps])
        cylinder(h = total_h + 2 * eps, d = bore_d);
}
