// L-shaped mounting bracket
// Print orientation: base plate flat on bed (z = 0), vertical plate rising along +Z at y = 0..5

$fn = 64;

// ---------- Base plate ----------
base_x_min = -25;   // base plate X start
base_x_max = 25;    // base plate X end
base_y_min = 0;     // base plate Y start (back edge)
base_y_max = 50;    // base plate Y end (front edge)
base_t     = 5;     // base plate thickness (Z)

// ---------- Vertical plate ----------
vert_y_t   = 5;     // vertical plate thickness (Y, from y = 0)
vert_h     = 45;    // vertical plate height (Z, from z = 0)

// ---------- Holes ----------
hole_d       = 5.5; // diameter of all mounting holes
base_hole_x  = 17;  // base hole X offset (+/-)
base_hole_y  = 38;  // base hole Y position
vert_hole_x  = 17;  // vertical-plate hole X offset (+/-)
vert_hole_z  = 30;  // vertical-plate hole Z position

eps = 0.5;          // cutter overshoot past faces

base_w = base_x_max - base_x_min;   // 50
base_l = base_y_max - base_y_min;   // 50

difference() {
    union() {
        // Base plate
        translate([base_x_min, base_y_min, 0])
            cube([base_w, base_l, base_t]);
        // Vertical plate
        translate([base_x_min, base_y_min, 0])
            cube([base_w, vert_y_t, vert_h]);
    }

    // Vertical through-holes in base plate (along Z)
    for (sx = [-1, 1])
        translate([sx * base_hole_x, base_hole_y, -eps])
            cylinder(d = hole_d, h = base_t + 2 * eps);

    // Horizontal through-holes in vertical plate (along Y)
    for (sx = [-1, 1])
        translate([sx * vert_hole_x, base_y_min - eps, vert_hole_z])
            rotate([-90, 0, 0])
                cylinder(d = hole_d, h = vert_y_t + 2 * eps);
}
