```openscad
// Small lab funnel - printed upright, wide opening at top
// Built as a rotate_extrude of a 2D wall profile so the wall is
// 1.2 mm thick (measured perpendicular to the surface) everywhere.

$fn = 128;

// ---------- Dimensions (mm) ----------
wall        = 1.2;    // wall thickness everywhere
spout_od    = 10.0;   // spout outer diameter
spout_h     = 25;     // spout height (z = 0 .. 25)
rim_od      = 60;     // cone outer diameter at rim
rim_z       = 55;     // rim height (top of funnel)

// ---------- Derived values ----------
r_spout_o   = spout_od / 2;               // 5.0  spout outer radius
r_spout_i   = r_spout_o - wall;           // 3.8  spout bore radius (7.6 mm bore)
r_rim_o     = rim_od / 2;                 // 30   rim outer radius
cone_h      = rim_z - spout_h;            // 30   cone height
cone_slope  = (r_rim_o - r_spout_o) / cone_h;          // dr/dz of the cone
dr_cone     = wall * sqrt(1 + cone_slope * cone_slope); // radial offset giving 1.2 mm normal wall
r_rim_i     = r_rim_o - dr_cone;          // rim inner radius
// height where the inner cone surface meets the spout bore
z_join_i    = spout_h + (r_spout_i + dr_cone - r_spout_o) / cone_slope;

// ---------- Model ----------
rotate_extrude(convexity = 4)
    polygon(points = [
        [r_spout_i, 0],          // bottom of bore
        [r_spout_o, 0],          // bottom of spout outside
        [r_spout_o, spout_h],    // spout / cone junction (outside)
        [r_rim_o,   rim_z],      // rim outer edge
        [r_rim_i,   rim_z],      // rim inner edge
        [r_spout_i, z_join_i]    // inner cone meets spout bore
    ]);
