// Snap-on C-clip for 8.0 mm lab-stand rod
// Printed flat: 2-D profile in XY, extruded along +Z

$fn = 128;

rod_d      = 8.0;               // inner diameter (rod)
wall       = 3.5;               // ring wall thickness
outer_d    = rod_d + 2*wall;    // outer diameter = 15.0
height     = 8.0;               // extrusion height (Z)
gap_w      = 5.6;               // opening width (y from -2.8 to 2.8)
eps        = 0.5;               // cutter overshoot

linear_extrude(height = height)
    difference() {
        circle(d = outer_d);
        // rod bore
        circle(d = rod_d);
        // opening on -X side: x < 0, -gap_w/2 < y < gap_w/2
        translate([-(outer_d/2 + eps), -gap_w/2])
            square([outer_d/2 + eps, gap_w]);
    }
