// Push-on cap for a 12.0 mm OD tube, printed open-end up

// ---------------- Parameters ----------------
tube_od        = 12.0;   // tube outer diameter (reference)
clearance      = 0.4;    // diametral clearance between tube and bore
cap_od         = 16.0;   // cap outer diameter
cap_h          = 12.0;   // total cap height
bore_d         = 12.8;   // blind bore diameter (tube_od + clearance)
end_thick      = 3.0;    // closed end thickness at the bottom
groove_count   = 10;     // number of vertical grip grooves
groove_d       = 2.0;    // grip groove diameter (half-cylinder on outer surface)
eps            = 0.5;    // overcut for clean boolean differences
$fn            = 96;     // resolution for curved surfaces

// ---------------- Model ----------------
difference() {
    // Main cylindrical body standing on the bed
    cylinder(d = cap_od, h = cap_h);

    // Blind bore from the top, leaving a closed end at the bottom
    translate([0, 0, end_thick])
        cylinder(d = bore_d, h = cap_h - end_thick + eps);

    // Vertical grip grooves, centred on the outer surface, full height
    for (i = [0 : groove_count - 1])
        rotate([0, 0, i * 360 / groove_count])
            translate([cap_od / 2, 0, -eps])
                cylinder(d = groove_d, h = cap_h + 2 * eps, $fn = 48);
}
