// Weighted base for vertical support rod - printed upright
$fn = 96;

// --- Disc ---
disc_d      = 70;    // base disc diameter
disc_h      = 5;     // base disc thickness (z = 0 to 5)

// --- Boss ---
boss_d      = 24;    // central boss diameter
boss_top_z  = 30;    // top of boss

// --- Rod bore ---
bore_d      = 12.0;  // blind bore diameter for rod
bore_bot_z  = 5;     // bottom of blind bore

// --- Set screw ---
screw_d     = 4.5;   // radial set-screw hole diameter
screw_z     = 24;    // height of set-screw axis

eps         = 0.5;   // cutter overshoot

difference() {
    union() {
        // Base disc
        cylinder(d = disc_d, h = disc_h);
        // Central boss (overlaps disc slightly for a clean union)
        translate([0, 0, disc_h - 0.01])
            cylinder(d = boss_d, h = boss_top_z - disc_h + 0.01);
    }

    // Blind rod bore from top down to z = 5
    translate([0, 0, bore_bot_z])
        cylinder(d = bore_d, h = boss_top_z - bore_bot_z + eps);

    // Radial set-screw hole from +X side into the bore
    translate([0, 0, screw_z])
        rotate([0, 90, 0])
            cylinder(d = screw_d, h = boss_d / 2 + eps);
}
