// 8-well agarose gel comb, printed flat on the bed

// ---------------- Parameters ----------------
plate_t      = 2.0;   // plate thickness (Z), mm
spine_len    = 62;    // spine (back bar) length (X), mm
spine_w      = 10;    // spine width (Y), mm
n_teeth      = 8;     // number of wells / teeth
tooth_w      = 5.0;   // tooth width (X), mm
tooth_len    = 12;    // tooth length (Y), mm
tooth_gap    = 2.0;   // gap between neighbouring teeth (X), mm
overlap      = 0.01;  // small overlap so teeth fuse into the spine

$fn = 64;

// ---------------- Derived ----------------
row_w     = n_teeth * tooth_w + (n_teeth - 1) * tooth_gap; // total width of tooth row
total_y   = spine_w + tooth_len;                           // overall Y extent
y_min     = -total_y / 2;                                  // tooth tips
y_spine0  = y_min + tooth_len;                             // spine/tooth junction

// ---------------- Model ----------------
union() {
    // Spine (back bar)
    translate([-spine_len / 2, y_spine0, 0])
        cube([spine_len, spine_w, plate_t]);

    // Teeth, centred on the spine in X, hanging in -Y
    for (i = [0 : n_teeth - 1])
        translate([-row_w / 2 + i * (tooth_w + tooth_gap), y_min, 0])
            cube([tooth_w, tooth_len + overlap, plate_t]);
}
