// Flat drilling / marking jig with 4 x 3 hole grid and orientation notch
// Print orientation: plate lies flat on the bed, z = 0 to plate_t

// ---------- Parameters ----------
plate_l      = 50;    // plate length along X (mm)
plate_w      = 40;    // plate width along Y (mm)
plate_t      = 5;     // plate thickness along Z (mm)

hole_d       = 4.0;   // through-hole diameter (mm)
hole_nx      = 4;     // number of holes along X
hole_ny      = 3;     // number of holes along Y
hole_pitch   = 10;    // centre-to-centre spacing, both directions (mm)

notch_w      = 10;    // orientation notch width along X (mm)
notch_d      = 4;     // orientation notch depth along Y, in from +Y edge (mm)

eps          = 0.5;   // overshoot for clean boolean cuts (mm)
$fn          = 64;    // resolution for round holes

// ---------- Model ----------
difference() {
    // Base plate, centred in X/Y, resting on z = 0
    translate([-plate_l/2, -plate_w/2, 0])
        cube([plate_l, plate_w, plate_t]);

    // 4 x 3 grid of through-holes, centred on the plate
    for (i = [0 : hole_nx - 1])
        for (j = [0 : hole_ny - 1])
            translate([(i - (hole_nx - 1)/2) * hole_pitch,
                       (j - (hole_ny - 1)/2) * hole_pitch,
                       -eps])
                cylinder(d = hole_d, h = plate_t + 2*eps);

    // Rectangular orientation notch on the +Y edge, centred on the Y axis
    translate([-notch_w/2, plate_w/2 - notch_d, -eps])
        cube([notch_w, notch_d + eps, plate_t + 2*eps]);
}
