// Two-part enclosure: open-top box + upside-down lid, printed side by side
// Units: mm

$fn = 64;

// ---------- Box ----------
box_x      = 80;    // box outer length (X)
box_y      = 60;    // box outer width (Y)
box_z      = 35;    // box outer height (Z)
wall_t     = 1.6;   // box side wall thickness
floor_t    = 1.6;   // box floor thickness

// ---------- Lid ----------
lid_x      = 80;    // lid plate length (X)
lid_y      = 60;    // lid plate width (Y)
lid_t      = 2.5;   // lid plate thickness
lip_x      = 76.4;  // lip outer length (X)
lip_y      = 56.4;  // lip outer width (Y)
lip_t      = 1.2;   // lip wall thickness
lip_h      = 4;     // lip height above plate

// ---------- Layout ----------
gap        = 10;    // gap between box and lid on the bed
eps        = 0.5;   // cutter overshoot

// Centre the pair of parts on the origin in X
box_cx = -(gap / 2 + box_x / 2);   // box centre X
lid_cx =  (gap / 2 + lid_x / 2);   // lid centre X (+X side)

// ---------- Part 1: box ----------
module box() {
    difference() {
        translate([-box_x / 2, -box_y / 2, 0])
            cube([box_x, box_y, box_z]);
        // inner cavity, open at top
        translate([-(box_x - 2 * wall_t) / 2, -(box_y - 2 * wall_t) / 2, floor_t])
            cube([box_x - 2 * wall_t, box_y - 2 * wall_t, box_z - floor_t + eps]);
    }
}

// ---------- Part 2: lid (printed upside down) ----------
module lid() {
    union() {
        // plate on the bed
        translate([-lid_x / 2, -lid_y / 2, 0])
            cube([lid_x, lid_y, lid_t]);
        // rectangular lip on top of plate
        difference() {
            translate([-lip_x / 2, -lip_y / 2, lid_t - 0.01])
                cube([lip_x, lip_y, lip_h + 0.01]);
            translate([-(lip_x - 2 * lip_t) / 2, -(lip_y - 2 * lip_t) / 2, lid_t - eps])
                cube([lip_x - 2 * lip_t, lip_y - 2 * lip_t, lip_h + 2 * eps]);
        }
    }
}

// ---------- Assembly on the bed ----------
translate([box_cx, 0, 0]) box();
translate([lid_cx, 0, 0]) lid();
