// Replacement control knob for 6.0 mm D-shaft
// Print orientation: hotplate-facing side (bore opening) down on the bed

$fn = 96;

// ---- Knob body ----
knob_d        = 25.0;   // knob outer diameter
knob_h        = 15.0;   // knob total height

// ---- D-shaped blind bore ----
bore_d        = 6.2;    // bore circle diameter (clearance for 6.0 shaft)
bore_flat     = 4.9;    // distance from flat to opposite side of circle
bore_depth    = 11.0;   // blind bore depth from bottom face

// ---- Grip grooves ----
groove_count  = 20;     // number of vertical grooves
groove_d      = 2.0;    // groove (half-cylinder) diameter

// ---- Helpers ----
eps           = 0.5;    // overshoot for clean boolean cuts
flat_offset   = bore_flat - bore_d / 2;   // flat position from bore centre (+Y)

// D-shaped 2D profile
module d_profile() {
    intersection() {
        circle(d = bore_d, $fn = 96);
        // keep everything below the flat
        translate([-bore_d, -bore_d])
            square([2 * bore_d, bore_d + flat_offset]);
    }
}

difference() {
    // Main knob cylinder
    cylinder(d = knob_d, h = knob_h, $fn = 128);

    // D-bore from the bottom face
    translate([0, 0, -eps])
        linear_extrude(height = bore_depth + eps)
            d_profile();

    // Grip grooves, centred on outer surface, full height
    for (i = [0 : groove_count - 1])
        rotate([0, 0, i * 360 / groove_count])
            translate([knob_d / 2, 0, -eps])
                cylinder(d = groove_d, h = knob_h + 2 * eps, $fn = 64);
}
